"""Soal latihan tambahan untuk jalur HTML, CSS, Frontend Pemula, Frontend, React, dan TypeScript."""
from mobile_dart_x import S


def H(q, h, a): return S(q, h, a, lang='html')
def CS(q, h, a): return S(q, h, a, lang='css')
def J(q, h, a, out=None): return S(q, h, a, out, lang='js')
def X(q, h, a, out=None): return S(q, h, a, out, lang='jsx')
def T(q, h, a, out=None): return S(q, h, a, out, lang='ts')
def Bs(q, h, a): return S(q, h, a, lang='bash')
def Tx(q, h, a): return S(q, h, a, lang='text')


